package io.github.diodeme.ji.workspace.local;

import io.github.diodeme.ji.ai.CancellationToken;
import io.github.diodeme.ji.error.ErrorCode;
import io.github.diodeme.ji.error.JiError;
import io.github.diodeme.ji.error.JiException;
import io.github.diodeme.ji.extension.WorkspaceProvider;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.channels.SeekableByteChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.OpenOption;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.nio.file.attribute.BasicFileAttributes;
import java.time.Duration;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.OptionalLong;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

/** Local filesystem/process adapter with workspace-root capabilities and open-time boundary checks. */
public final class LocalWorkspaceProvider implements WorkspaceProvider {
    private static final Set<String> DEFAULT_ENVIRONMENT = Set.of(
            "PATH", "PATHEXT", "SYSTEMROOT", "COMSPEC", "TEMP", "TMP", "HOME", "USERPROFILE", "LANG", "LC_ALL");
    private static final int PROCESS_OUTPUT_LIMIT = 50 * 1_024;
    private final WorkspaceIdentity identity;
    private final List<Path> roots;
    private final Set<String> environmentAllowlist;
    private final Set<String> environmentDenylist;
    private final Map<String, FileState> revisions = new ConcurrentHashMap<>();
    private final Map<String, Object> mutationLocks = new ConcurrentHashMap<>();
    private final AtomicBoolean closed = new AtomicBoolean();

    public LocalWorkspaceProvider(String workspaceId, Path root) {
        this(workspaceId, 0, root, List.of(), DEFAULT_ENVIRONMENT,
                Set.of("JAVA_TOOL_OPTIONS", "JDK_JAVA_OPTIONS", "CLASSPATH"));
    }

    public LocalWorkspaceProvider(String workspaceId, long generation, Path root, List<Path> additionalRoots,
                                  Set<String> environmentAllowlist, Set<String> environmentDenylist) {
        identity = new WorkspaceIdentity(workspaceId, generation);
        if (root == null || additionalRoots == null || environmentAllowlist == null || environmentDenylist == null) {
            throw new IllegalArgumentException("workspace configuration must not be null");
        }
        var configuredRoots = new ArrayList<Path>();
        configuredRoots.add(canonicalExistingDirectory(root));
        for (Path additional : additionalRoots) configuredRoots.add(canonicalExistingDirectory(additional));
        roots = List.copyOf(configuredRoots);
        this.environmentAllowlist = normalizeNames(environmentAllowlist);
        this.environmentDenylist = normalizeNames(environmentDenylist);
    }

    @Override
    public WorkspaceIdentity identity() {
        return identity;
    }

    @Override
    public WorkspacePath resolve(String rawPath, Access access) {
        requireOpen();
        if (rawPath == null || rawPath.isBlank() || rawPath.indexOf('\0') >= 0) {
            throw error(ErrorCode.WORKSPACE_INVALID_PATH,
                    Map.of("path", String.valueOf(rawPath), "reason", "blank_or_nul"));
        }
        Path supplied;
        try {
            supplied = Path.of(normalizeSeparators(rawPath));
        } catch (RuntimeException exception) {
            throw error(ErrorCode.WORKSPACE_INVALID_PATH,
                    Map.of("path", rawPath, "reason", "invalid_syntax"), exception);
        }
        Path candidate = supplied.isAbsolute() ? supplied.toAbsolutePath().normalize()
                : roots.getFirst().resolve(supplied).normalize();
        Path canonical = canonicalCandidate(candidate, rawPath);
        Path owner = owningRoot(canonical);
        if (owner == null) throw outside(rawPath);
        String relative = portable(owner.relativize(canonical));
        if (relative.isEmpty()) relative = ".";
        return new WorkspacePath(identity, portable(canonical), relative, access, identity.generation());
    }

    @Override
    public FileContent read(WorkspacePath capability, ReadOptions options, CancellationToken cancellation) {
        requireOpen();
        requireCapability(capability, Access.READ);
        cancellation.throwIfCancellationRequested();
        Path path = checkedPath(capability, false);
        if (!Files.isRegularFile(path)) throw error(ErrorCode.WORKSPACE_NOT_FOUND, Map.of("path", capability.relativePath()));
        try (SeekableByteChannel channel = Files.newByteChannel(path, Set.of(StandardOpenOption.READ, LinkOption.NOFOLLOW_LINKS))) {
            Path afterOpen = checkedPath(capability, true);
            BasicFileAttributes before = Files.readAttributes(afterOpen, BasicFileAttributes.class, LinkOption.NOFOLLOW_LINKS);
            if (!before.isRegularFile()) throw error(ErrorCode.WORKSPACE_NOT_FOUND, Map.of("path", capability.relativePath()));
            byte[] all = readAll(channel, cancellation);
            BasicFileAttributes after = Files.readAttributes(afterOpen, BasicFileAttributes.class, LinkOption.NOFOLLOW_LINKS);
            if (!sameFile(before, after)) throw stale(capability);
            long revision = observeRevision(path, after);
            return sliceText(all, revision, options, capability.relativePath());
        } catch (JiException exception) {
            throw exception;
        } catch (IOException exception) {
            throw error(ErrorCode.WORKSPACE_NOT_FOUND, Map.of("path", capability.relativePath()), exception);
        }
    }

    @Override
    public MutationResult write(WorkspacePath capability, byte[] content, OptionalLong expectedRevision,
                                CancellationToken cancellation) {
        requireOpen();
        requireCapability(capability, Access.WRITE);
        if (content == null || expectedRevision == null) throw new IllegalArgumentException("write fields must not be null");
        String key = [REDACTED_CREDENTIAL]
        synchronized (mutationLocks.computeIfAbsent(key, ignored -> new Object())) {
            cancellation.throwIfCancellationRequested();
            Path target = checkedPath(capability, false);
            ensureParentDirectories(target.getParent(), capability.relativePath());
            target = checkedPath(capability, false);
            long current = currentRevision(target);
            requireRevision(capability.relativePath(), expectedRevision, current);
            Path parent = target.getParent();
            Path temporary = null;
            try {
                temporary = Files.createTempFile(parent, ".ji-write-", ".tmp");
                requireInside(canonicalCandidate(temporary, capability.relativePath()), capability.relativePath());
                Files.write(temporary, content, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
                cancellation.throwIfCancellationRequested();
                checkedPath(capability, false);
                requireInside(parent.toRealPath(), capability.relativePath());
                atomicReplace(temporary, target);
                temporary = null;
                BasicFileAttributes attributes = Files.readAttributes(target, BasicFileAttributes.class, LinkOption.NOFOLLOW_LINKS);
                long revision = nextRevision(key, attributes, current);
                return new MutationResult(revision, content.length);
            } catch (JiException exception) {
                throw exception;
            } catch (IOException exception) {
                throw error(ErrorCode.TOOL_EXECUTION_FAILED, Map.of("tool", "write"), exception);
            } finally {
                if (temporary != null) {
                    try { Files.deleteIfExists(temporary); } catch (IOException ignored) { }
                }
            }
        }
    }

    @Override
    public MutationResult edit(WorkspacePath capability, List<Replacement> replacements, long expectedRevision,
                               CancellationToken cancellation) {
        requireOpen();
        requireCapability(capability, Access.WRITE);
        replacements = List.copyOf(replacements);
        if (replacements.isEmpty()) throw new IllegalArgumentException("replacements must not be empty");
        String key = [REDACTED_CREDENTIAL]
        synchronized (mutationLocks.computeIfAbsent(key, ignored -> new Object())) {
            Path path = checkedPath(capability, true);
            long current = currentRevision(path);
            requireRevision(capability.relativePath(), OptionalLong.of(expectedRevision), current);
            cancellation.throwIfCancellationRequested();
            byte[] bytes;
            try {
                bytes = Files.readAllBytes(path);
            } catch (IOException exception) {
                throw error(ErrorCode.WORKSPACE_NOT_FOUND, Map.of("path", capability.relativePath()), exception);
            }
            String raw = new String(bytes, StandardCharsets.UTF_8);
            String bom = raw.startsWith("﻿") ? "﻿" : "";
            String original = bom.isEmpty() ? raw : raw.substring(1);
            List<Match> matches = exactMatches(original, replacements, capability.relativePath());
            var result = new StringBuilder(original);
            matches.stream().sorted((left, right) -> Integer.compare(right.offset(), left.offset())).forEach(match ->
                    result.replace(match.offset(), match.offset() + match.length(), match.replacement()));
            return write(capability, (bom + result).getBytes(StandardCharsets.UTF_8), OptionalLong.of(current), cancellation);
        }
    }

    @Override
    public ProcessResult execute(ProcessRequest request, CancellationToken cancellation) {
        requireOpen();
        if (!identity.equals(request.workspace())) throw stale(request.cwd());
        requireCapability(request.cwd(), Access.EXECUTE);
        Path cwd = checkedPath(request.cwd(), true);
        if (!Files.isDirectory(cwd)) throw error(ErrorCode.WORKSPACE_NOT_FOUND, Map.of("path", request.cwd().relativePath()));
        List<String> command = command(request.command());
        Map<String, String> environment = filteredEnvironment(request.environment());
        cancellation.throwIfCancellationRequested();
        checkedPath(request.cwd(), true);
        Process process;
        try {
            ProcessBuilder builder = new ProcessBuilder(command).directory(cwd.toFile()).redirectErrorStream(false);
            builder.environment().clear();
            builder.environment().putAll(environment);
            process = builder.start();
        } catch (IOException exception) {
            throw error(ErrorCode.TOOL_EXECUTION_FAILED, Map.of("tool", "shell"), exception);
        }
        var out = new TailCapture(PROCESS_OUTPUT_LIMIT);
        var err = new TailCapture(PROCESS_OUTPUT_LIMIT);
        Thread outThread = Thread.ofVirtual().start(() -> out.copy(process.getInputStream()));
        Thread errThread = Thread.ofVirtual().start(() -> err.copy(process.getErrorStream()));
        cancellation.cancellation().thenRun(() -> destroy(process));
        try {
            boolean exited = process.waitFor(request.timeout().toMillis(), TimeUnit.MILLISECONDS);
            if (!exited) {
                destroy(process);
                throw error(ErrorCode.TOOL_EXECUTION_FAILED, Map.of("tool", "shell"));
            }
            if (cancellation.isCancellationRequested()) {
                throw error(ErrorCode.OPERATION_CANCELLED, Map.of("operationId", "shell"));
            }
            outThread.join(Duration.ofSeconds(5));
            errThread.join(Duration.ofSeconds(5));
            return new ProcessResult(process.exitValue(), out.bytes(), err.bytes(), out.truncated(), err.truncated());
        } catch (InterruptedException exception) {
            Thread.currentThread().interrupt();
            destroy(process);
            throw error(ErrorCode.OPERATION_CANCELLED, Map.of("operationId", "shell"), exception);
        } finally {
            if (process.isAlive()) destroy(process);
        }
    }

    @Override
    public void close() {
        closed.set(true);
    }

    private Path checkedPath(WorkspacePath capability, boolean mustExist) {
        requireCapability(capability, capability.access());
        Path path = Path.of(capability.canonicalPath());
        Path actual = canonicalCandidate(path, capability.relativePath());
        requireInside(actual, capability.relativePath());
        if (!samePath(path, actual)) throw stale(capability);
        if (mustExist && !Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
            throw error(ErrorCode.WORKSPACE_NOT_FOUND, Map.of("path", capability.relativePath()));
        }
        return path;
    }

    private void requireCapability(WorkspacePath capability, Access expected) {
        if (capability == null || !identity.equals(capability.workspace())
                || capability.capabilityRevision() != identity.generation() || capability.access() != expected) {
            throw stale(capability);
        }
    }

    private Path canonicalCandidate(Path candidate, String display) {
        Path absolute = candidate.toAbsolutePath().normalize();
        Path existing = absolute;
        var missing = new ArrayList<Path>();
        while (existing != null && !Files.exists(existing, LinkOption.NOFOLLOW_LINKS)) {
            Path name = existing.getFileName();
            if (name != null) missing.add(name);
            existing = existing.getParent();
        }
        if (existing == null) throw outside(display);
        try {
            Path canonical = existing.toRealPath();
            for (int index = missing.size() - 1; index >= 0; index--) canonical = canonical.resolve(missing.get(index));
            return canonical.normalize();
        } catch (IOException exception) {
            throw error(ErrorCode.WORKSPACE_INVALID_PATH, Map.of("path", display, "reason", "canonicalize_failed"), exception);
        }
    }

    private void ensureParentDirectories(Path parent, String display) {
        if (parent == null) throw outside(display);
        Path canonicalParent = canonicalCandidate(parent, display);
        requireInside(canonicalParent, display);
        Path owner = owningRoot(canonicalParent);
        if (owner == null) throw outside(display);
        Path current = owner;
        Path relative = owner.relativize(canonicalParent);
        try {
            for (Path segment : relative) {
                current = current.resolve(segment);
                if (!Files.exists(current, LinkOption.NOFOLLOW_LINKS)) Files.createDirectory(current);
                Path actual = current.toRealPath();
                requireInside(actual, display);
                current = actual;
            }
        } catch (IOException exception) {
            throw error(ErrorCode.TOOL_EXECUTION_FAILED, Map.of("tool", "write"), exception);
        }
    }

    private Path owningRoot(Path path) {
        for (Path root : roots) if (isWithin(path, root)) return root;
        return null;
    }

    private void requireInside(Path path, String display) {
        if (owningRoot(path) == null) throw outside(display);
    }

    private long currentRevision(Path path) {
        if (!Files.exists(path, LinkOption.NOFOLLOW_LINKS)) return 0;
        try {
            BasicFileAttributes attributes = Files.readAttributes(path, BasicFileAttributes.class, LinkOption.NOFOLLOW_LINKS);
            return observeRevision(path, attributes);
        } catch (IOException exception) {
            throw error(ErrorCode.WORKSPACE_NOT_FOUND, Map.of("path", portable(path)), exception);
        }
    }

    private long observeRevision(Path path, BasicFileAttributes attributes) {
        String key = [REDACTED_CREDENTIAL]
        Fingerprint fingerprint = Fingerprint.of(attributes);
        return revisions.compute(key, (ignored, prior) -> {
            if (prior == null) return new FileState(1, fingerprint);
            return prior.fingerprint().equals(fingerprint) ? prior : new FileState(prior.revision() + 1, fingerprint);
        }).revision();
    }

    private long nextRevision(String key, BasicFileAttributes attributes, long current) {
        long next = current + 1;
        revisions.put(key, new FileState(next, Fingerprint.of(attributes)));
        return next;
    }

    private static FileContent sliceText(byte[] all, long revision, ReadOptions options, String path) {
        String content = new String(all, options.charset());
        String[] lines = content.split("\\n", -1);
        int totalLines = lines.length;
        long startLong = options.offset() - 1;
        if (startLong >= totalLines) {
            throw error(ErrorCode.WORKSPACE_INVALID_PATH,
                    Map.of("path", path, "reason", "offset_beyond_end"));
        }
        int start = Math.toIntExact(startLong);
        int requestedEnd = (int) Math.min(totalLines, startLong + options.limit());
        var selected = new StringBuilder();
        String truncatedBy = "";
        int outputLines = 0;
        for (int index = start; index < requestedEnd && outputLines < options.maxLines(); index++) {
            String prefix = outputLines == 0 ? "" : "\n";
            byte[] candidate = (prefix + lines[index]).getBytes(options.charset());
            if (selected.toString().getBytes(options.charset()).length + candidate.length > options.maxBytes()) {
                truncatedBy = "bytes";
                break;
            }
            selected.append(prefix).append(lines[index]);
            outputLines++;
        }
        if (truncatedBy.isEmpty() && outputLines < requestedEnd - start) truncatedBy = "lines";
        boolean truncated = start + outputLines < totalLines;
        long nextOffset = truncated ? options.offset() + outputLines : 0;
        return new FileContent(selected.toString().getBytes(options.charset()), revision, totalLines,
                truncated, truncated ? (truncatedBy.isEmpty() ? "limit" : truncatedBy) : "", nextOffset);
    }

    private static List<Match> exactMatches(String original, List<Replacement> replacements, String path) {
        var matches = new ArrayList<Match>();
        for (int index = 0; index < replacements.size(); index++) {
            Replacement replacement = replacements.get(index);
            int first = original.indexOf(replacement.oldText());
            int second = first < 0 ? -1 : original.indexOf(replacement.oldText(), first + 1);
            int count = first < 0 ? 0 : second < 0 ? 1 : 2;
            if (count != 1) throw error(ErrorCode.EDIT_MATCH_CONFLICT,
                    Map.of("path", path, "editIndex", Integer.toString(index), "matches", Integer.toString(count)));
            int end = first + replacement.oldText().length();
            for (Match existing : matches) {
                if (first < existing.offset() + existing.length() && existing.offset() < end) {
                    throw error(ErrorCode.EDIT_MATCH_CONFLICT,
                            Map.of("path", path, "editIndex", Integer.toString(index), "matches", "overlap"));
                }
            }
            matches.add(new Match(first, replacement.oldText().length(), replacement.newText()));
        }
        return matches;
    }

    private Map<String, String> filteredEnvironment(Map<String, String> explicit) {
        Map<String, String> result = new HashMap<>();
        System.getenv().forEach((name, value) -> {
            String normalized = normalizeName(name);
            if (environmentAllowlist.contains(normalized) && !environmentDenylist.contains(normalized)
                    && !looksSensitive(normalized)) result.put(name, value);
        });
        explicit.forEach((name, value) -> {
            String normalized = normalizeName(name);
            if (!environmentAllowlist.contains(normalized) || environmentDenylist.contains(normalized)
                    || looksSensitive(normalized)) {
                throw error(ErrorCode.SHELL_ENVIRONMENT_DENIED, Map.of("name", name));
            }
            result.put(name, value);
        });
        return result;
    }

    private static List<String> command(Command command) {
        if (command instanceof Command.Argv argv) return argv.arguments();
        String value = ((Command.Shell) command).command();
        if (isWindows()) return List.of("pwsh", "-NoProfile", "-NonInteractive", "-Command", value);
        return List.of("/bin/sh", "-c", value);
    }

    private static void atomicReplace(Path temporary, Path target) throws IOException {
        try {
            Files.move(temporary, target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
        } catch (AtomicMoveNotSupportedException exception) {
            throw new IOException("workspace filesystem does not support required atomic replacement", exception);
        }
    }

    private static byte[] readAll(SeekableByteChannel channel, CancellationToken cancellation) throws IOException {
        var output = new ByteArrayOutputStream();
        ByteBuffer buffer = ByteBuffer.allocate(8 * 1_024);
        while (channel.read(buffer) >= 0) {
            cancellation.throwIfCancellationRequested();
            buffer.flip();
            output.write(buffer.array(), 0, buffer.remaining());
            buffer.clear();
        }
        return output.toByteArray();
    }

    private static boolean sameFile(BasicFileAttributes left, BasicFileAttributes right) {
        if (left.fileKey() != null && right.fileKey() != null) return left.fileKey().equals(right.fileKey());
        return left.size() == right.size() && left.lastModifiedTime().equals(right.lastModifiedTime());
    }

    private static boolean isWithin(Path path, Path root) {
        if (!isWindows()) return path.normalize().startsWith(root.normalize());
        String candidate = portable(path).toLowerCase(Locale.ROOT);
        String prefix = portable(root).toLowerCase(Locale.ROOT);
        return candidate.equals(prefix) || candidate.startsWith(prefix.endsWith("/") ? prefix : prefix + "/");
    }

    private static boolean samePath(Path left, Path right) {
        return isWindows() ? portable(left).equalsIgnoreCase(portable(right)) : left.equals(right);
    }

    private static Path canonicalExistingDirectory(Path root) {
        try {
            Path canonical = root.toRealPath();
            if (!Files.isDirectory(canonical)) throw new IllegalArgumentException("workspace root must be a directory");
            return canonical;
        } catch (IOException exception) {
            throw new IllegalArgumentException("workspace root must exist", exception);
        }
    }

    private static Set<String> normalizeNames(Set<String> values) {
        var result = new HashSet<String>();
        values.forEach(value -> result.add(normalizeName(value)));
        return Set.copyOf(result);
    }

    private static String normalizeName(String value) {
        return isWindows() ? value.toUpperCase(Locale.ROOT) : value;
    }

    private static boolean looksSensitive(String name) {
        String upper = name.toUpperCase(Locale.ROOT);
        return upper.contains("TOKEN") || upper.contains("SECRET") || upper.contains("PASSWORD")
                || upper.endsWith("_KEY") || upper.contains("CREDENTIAL");
    }

    private static String normalizeSeparators(String path) {
        return isWindows() ? path.replace('/', '\\') : path;
    }

    private static String portable(Path path) {
        return path.toString().replace('\\', '/');
    }

    private static boolean isWindows() {
        return System.getProperty("os.name", "").toLowerCase(Locale.ROOT).contains("win");
    }

    private void requireOpen() {
        if (closed.get()) throw error(ErrorCode.RUNTIME_CLOSED, Map.of("resource", "workspace"));
    }

    private static void requireRevision(String path, OptionalLong expected, long current) {
        if (expected.isPresent() && expected.getAsLong() != current) {
            throw error(ErrorCode.WORKSPACE_REVISION_CONFLICT,
                    Map.of("path", path, "expectedRevision", Long.toString(expected.getAsLong()),
                            "currentRevision", Long.toString(current)));
        }
    }

    private JiException outside(String path) {
        return error(ErrorCode.WORKSPACE_PATH_OUTSIDE,
                Map.of("workspaceId", identity.workspaceId(), "path", path));
    }

    private JiException stale(WorkspacePath path) {
        String relative = path == null ? "unknown" : path.relativePath();
        String workspaceId = path == null ? identity.workspaceId() : path.workspace().workspaceId();
        return error(ErrorCode.WORKSPACE_STALE_CAPABILITY, Map.of("workspaceId", workspaceId, "path", relative));
    }

    private static JiException error(ErrorCode code, Map<String, String> parameters) {
        return error(code, parameters, null);
    }

    private static JiException error(ErrorCode code, Map<String, String> parameters, Throwable cause) {
        JiError error = new JiError(code, parameters, java.util.Optional.empty(), java.util.Optional.empty(), OptionalLong.empty());
        return cause == null ? new JiException(error) : new JiException(error, cause);
    }

    private static void destroy(Process process) {
        process.descendants().forEach(ProcessHandle::destroyForcibly);
        process.destroyForcibly();
    }

    private record Match(int offset, int length, String replacement) {}
    private record FileState(long revision, Fingerprint fingerprint) {}
    private record Fingerprint(Object key, long size, long modifiedMillis) {
        static Fingerprint of(BasicFileAttributes attributes) {
            return new Fingerprint(attributes.fileKey(), attributes.size(), attributes.lastModifiedTime().toMillis());
        }
    }

    private static final class TailCapture {
        private final int limit;
        private byte[] bytes = new byte[0];
        private boolean truncated;

        TailCapture(int limit) { this.limit = limit; }

        synchronized void copy(InputStream input) {
            byte[] buffer = new byte[8 * 1_024];
            try (input) {
                int read;
                while ((read = input.read(buffer)) >= 0) append(buffer, read);
            } catch (IOException ignored) { }
        }

        private synchronized void append(byte[] incoming, int count) {
            byte[] combined = new byte[bytes.length + count];
            System.arraycopy(bytes, 0, combined, 0, bytes.length);
            System.arraycopy(incoming, 0, combined, bytes.length, count);
            if (combined.length > limit) {
                truncated = true;
                bytes = java.util.Arrays.copyOfRange(combined, combined.length - limit, combined.length);
            } else {
                bytes = combined;
            }
        }

        synchronized byte[] bytes() { return bytes.clone(); }
        synchronized boolean truncated() { return truncated; }
    }
}
